import re

from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone


class CatBraces(GenericUnixCommand):
    """Command cat_braces."""

    def __init__(self, connection, path="/ffs/run/trs_data/active/dhcpd_sfn.leases", prompt=None, newline_chars=None, runner=None):
        """
        Command cat_braces.

        :param connection: moler connection to device, terminal when command is executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(CatBraces, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.path = path
        self.ip = None
        self.number = None
        self.num = 0
        self.date = ["DAY_OF_WEEK", "YEAR", "MONTH", "DAY", "HOURS", "MINUTES", "SECONDS"]

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"cat {self.path}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_lease(line)
                self._parse_date(line)
                self._parse_binding_state(line)
                self._parse_next_binding_state(line)
                self._parse_rewind_binding_state(line)
                self._parse_hardware(line)
                self._parse_set(line)
            except ParsingDone:
                pass
        return super(CatBraces, self).on_new_line(line, is_full_line)

    # lease 192.168.252.4 {
    _re_lease = re.compile(r"lease\s(?P<IP>[\.\d]+)\s\{")

    def _parse_lease(self, line):
        if self._regex_helper.search_compiled(CatBraces._re_lease, line):
            if self._regex_helper.group("IP") in self.current_ret:
                self.num = self.num + 1
            else:
                self.num = 0
                self.current_ret[self._regex_helper.group("IP")] = {}
            self.number = str(self.num)
            self.ip = self._regex_helper.group("IP")
            self.current_ret[self.ip][self.number] = {}
            raise ParsingDone

    #   starts 2 2016/08/16 08:38:46;
    _re_date = re.compile(
        r"(?P<HEADER>\S+)\s(?P<DAY_OF_WEEK>\d+)\s(?P<YEAR>\d+)\/(?P<MONTH>\d+)\/(?P<DAY>\d+)\s(?P<HOURS>\d+):(?P<MINUTES>\d+):(?P<SECONDS>\d+);"
    )

    def _parse_date(self, line):
        if self._regex_helper.search_compiled(CatBraces._re_date, line):
            self.current_ret[self.ip][self.number][self._regex_helper.group("HEADER").upper()] = {}
            for el in self.date:
                self.current_ret[self.ip][self.number][self._regex_helper.group("HEADER").upper()][el] = self._regex_helper.group(el)
            raise ParsingDone

    #   binding state free;
    _re_binding_state = re.compile(r"^\s+binding\sstate\s(?P<STATE>\S+);")

    def _parse_binding_state(self, line):
        if self._regex_helper.search_compiled(CatBraces._re_binding_state, line):
            self.current_ret[self.ip][self.number]["BINDING_STATE"] = self._regex_helper.group("STATE")
            raise ParsingDone

    #   next binding state free;
    _re_next_binding_state = re.compile(r"^\s+next\sbinding\sstate\s(?P<STATE>\S+);")

    def _parse_next_binding_state(self, line):
        if self._regex_helper.search_compiled(CatBraces._re_next_binding_state, line):
            self.current_ret[self.ip][self.number]["NEXT_BINDING_STATE"] = self._regex_helper.group("STATE")
            raise ParsingDone

    #   rewind binding state free;
    _re_rewind_binding_state = re.compile(r"^\s+rewind\sbinding\sstate\s(?P<STATE>\S+);")

    def _parse_rewind_binding_state(self, line):
        if self._regex_helper.search_compiled(CatBraces._re_rewind_binding_state, line):
            self.current_ret[self.ip][self.number]["REWIND_BINDING_STATE"] = self._regex_helper.group("STATE")
            raise ParsingDone

    #   hardware ethernet 60:a8:fe:74:f1:8a;
    _re_hardware = re.compile(r"hardware\s(?P<TYPE>\S+)\s(?P<MAC>\S+);")

    def _parse_hardware(self, line):
        if self._regex_helper.search_compiled(CatBraces._re_hardware, line):
            self.current_ret[self.ip][self.number]["HARDWARE"] = {}
            self.current_ret[self.ip][self.number]["HARDWARE"]["HARDWARE_TYPE"] = self._regex_helper.group("TYPE")
            self.current_ret[self.ip][self.number]["HARDWARE"]["MAC_ADDRESS"] = self._regex_helper.group("MAC")
            raise ParsingDone

    #   set vendor-class-identifier = "NSNBTS01";
    _re_set = re.compile(r"^\s+set\s(?P<VARIABLE>\S+)\s=\s.?(?P<VALUE>[^\"]+).?;")

    def _parse_set(self, line):
        if self._regex_helper.search_compiled(CatBraces._re_set, line):
            self.current_ret[self.ip][self.number]["SET"] = {}
            self.current_ret[self.ip][self.number]["SET"]["VARIABLE"] = self._regex_helper.group("VARIABLE")
            self.current_ret[self.ip][self.number]["SET"]["VALUE"] = self._regex_helper.group("VALUE")
            raise ParsingDone


